-- The login banner and the minimap tooltip.
L["Click to open the settings"] = "Clique para abrir as configurações";
L["Circular class, spec and role icons on every nameplate, live crowd-control icons and instant Healer CC alerts."] = "Ícones circulares de classe, especialização e função em cada placa de nome, ícones de controle ao vivo e avisos instantâneos de controle no curandeiro.";
L["OPlates only adds icons. Your nameplate addon keeps its own bars and style."] = "O OPlates só adiciona ícones. Seu addon de placas de nome mantém as próprias barras e o próprio estilo.";
